-- ChubbyLu Bakery POS v0.17.0 — protected portable business export
create table if not exists public.backup_exports(id uuid primary key default gen_random_uuid(),shop_id uuid not null references public.shops(id) on delete cascade,schema_version text not null,requested_by uuid not null references auth.users(id) on delete restrict,requested_at timestamptz not null default now());alter table public.backup_exports enable row level security;create policy backup_exports_admin_select on public.backup_exports for select to authenticated using(shop_id=public.current_shop_id() and public.is_admin());

create or replace function public.export_business_backup() returns jsonb language plpgsql security definer set search_path=public as $$declare v_shop uuid:=public.current_shop_id();v_export uuid;v_now timestamptz:=now();begin if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required';end if;insert into public.backup_exports(shop_id,schema_version,requested_by) values(v_shop,'0.17.0',auth.uid()) returning id into v_export;return jsonb_build_object(
'schema_version','0.17.0','export_id',v_export,'exported_at',v_now,'shop',(select to_jsonb(s) from public.shops s where id=v_shop),
'staff',(select coalesce(jsonb_agg(jsonb_build_object('user_id',user_id,'display_name',display_name,'email',email,'role',role,'active',active,'created_at',created_at) order by display_name),'[]'::jsonb) from public.staff_profiles where shop_id=v_shop),
'categories',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.categories t where shop_id=v_shop),'products',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.products t where shop_id=v_shop),'customers',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.customers t where shop_id=v_shop),
'loyalty_programs',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.loyalty_programs t where shop_id=v_shop),'loyalty_memberships',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.loyalty_memberships t where shop_id=v_shop),'loyalty_rewards',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.loyalty_rewards t where shop_id=v_shop),'loyalty_point_transactions',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.loyalty_point_transactions t where shop_id=v_shop),'loyalty_stamp_transactions',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.loyalty_stamp_transactions t where shop_id=v_shop),
'sales',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.sales t where shop_id=v_shop),'sale_items',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.sale_items t where shop_id=v_shop),'sale_refunds',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.sale_refunds t where shop_id=v_shop),'sale_refund_items',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.sale_refund_items t where shop_id=v_shop),'receipt_reprints',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.receipt_reprints t where shop_id=v_shop),'inventory_adjustments',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.inventory_adjustments t where shop_id=v_shop),
'cash_drawer_sessions',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.cash_drawer_sessions t where shop_id=v_shop),'cash_drawer_transactions',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.cash_drawer_transactions t where shop_id=v_shop),'expense_categories',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.expense_categories t where shop_id=v_shop),'expenses',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.expenses t where shop_id=v_shop),
'suppliers',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.suppliers t where shop_id=v_shop),'stock_receipts',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.stock_receipts t where shop_id=v_shop),'purchase_orders',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.purchase_orders t where shop_id=v_shop),'purchase_order_items',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.purchase_order_items t where shop_id=v_shop),'purchase_order_events',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.purchase_order_events t where shop_id=v_shop),'production_batches',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.production_batches t where shop_id=v_shop),'staff_access_audit',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.staff_access_audit t where shop_id=v_shop)
);end $$;

create or replace function public.get_backup_history() returns jsonb language plpgsql security definer stable set search_path=public as $$declare v_shop uuid:=public.current_shop_id();begin if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required';end if;return(select coalesce(jsonb_agg(to_jsonb(x) order by x.requested_at desc),'[]'::jsonb) from(select b.id,b.requested_at,b.schema_version,coalesce(sp.display_name,'Former staff') requested_by_name from public.backup_exports b left join public.staff_profiles sp on sp.user_id=b.requested_by and sp.shop_id=b.shop_id where b.shop_id=v_shop order by b.requested_at desc limit 50)x);end $$;
revoke all on function public.export_business_backup() from public;revoke all on function public.get_backup_history() from public;grant execute on function public.export_business_backup() to authenticated;grant execute on function public.get_backup_history() to authenticated;
